var Q = require(require('path').join(process.env.STOCK_DASHBOARD_QUELLE || '.', 'quant.js'));
function signal(bars, i, params) {
  // Letzte Kerze des Monats: Indexfonds und Pensionskassen muessen zum Monatsende ihr Gewicht anpassen
  if (!bars[i + 1]) return null;
  var d = new Date(bars[i][0]), n = new Date(bars[i + 1][0]);
  return d.getUTCMonth() !== n.getUTCMonth() ? { dir: 1 } : null;
}
module.exports = {
  key: "monatsende-kauf",
  grund: "Indexfonds und Pensionskassen passen zum Monatsende ihre Gewichte an und MUESSEN dafuer kaufen - ein Zufluss mit Termin, kein Preismuster.",
  zeitrahmen: '60m',
  haltedauerKerzen: 8,
  richtung: "long",
  universum: 'aktien',
  kosten: { spanneBp: 5 },
  signal: signal,
};
